import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { readFile, stat } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { dirname, resolve } from 'node:path'

// Verify the *npm package contents*, not just the existence of a source stylesheet.
// `--ignore-scripts` is essential: a missing build artifact must fail instead
// of being silently regenerated by `prepack` during this verification.
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const pkg = JSON.parse(await readFile(resolve(root, 'package.json'), 'utf8'))
const entry = pkg.exports?.['./style.css']
assert.equal(entry, './dist/style.css', 'The CSS subpath must export dist/style.css')
assert.ok(pkg.sideEffects?.includes('./dist/style.css'), 'The CSS must be declared as a side effect for bundlers')
assert.ok(pkg.files?.includes('dist'), 'The publish allowlist must include dist/')

const sourceCss = await readFile(resolve(root, 'src/style.css'))
const builtCss = await readFile(resolve(root, 'dist/style.css'))
assert.ok(sourceCss.length > 0, 'The source stylesheet must not be empty')
assert.deepEqual(builtCss, sourceCss, 'The published stylesheet must match src/style.css')
const entryFile = await stat(resolve(root, pkg.exports['.'].import))
assert.ok(entryFile.size > 0, 'The JS export must exist and be nonempty')
const declarationFile = await stat(resolve(root, pkg.exports['.'].types))
assert.ok(declarationFile.size > 0, 'The TypeScript declaration export must exist and be nonempty')

const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm'
const packed = spawnSync(npm, ['pack', '--ignore-scripts', '--dry-run', '--json'], {
  cwd: root,
  encoding: 'utf8',
  shell: process.platform === 'win32',
})
if (packed.error) throw packed.error
assert.equal(packed.status, 0, `npm pack failed: ${packed.stderr || packed.stdout}`)
const [manifest] = JSON.parse(packed.stdout)
assert.equal(manifest.name, pkg.name)
assert.equal(manifest.version, pkg.version)
const packagedPaths = new Set(manifest.files.map(file => file.path))
for (const required of ['dist/style.css', 'dist/index.js', 'dist/index.d.ts', 'package.json']) {
  assert.ok(packagedPaths.has(required), `npm tarball is missing ${required}`)
}
assert.ok(![...packagedPaths].some(file => file.startsWith('src/') || file.startsWith('.internal/')), 'Do not publish src or .internal')
console.log(`Package verification passed: ${manifest.name}@${manifest.version}, CSS export and ${manifest.files.length} npm files.`)
